import React from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const EventsSlider = () => {
  const settings = {
    dots: true, // Alt nokta göstergeleri
    infinite: true, // Sonsuz kaydırma
    speed: 500, // Kaydırma hızı
    slidesToShow: 1, // Her seferde 1 slide göster
    slidesToScroll: 1, // 1 slide kaydır
    arrows: true, // Ok işaretleri
  };

  return (
    <div
      style={{
        position: "relative",
        maxWidth: "1024px",
        height: "400px", // Slider yüksekliği
        margin: "30px auto", // Ortalamak için
        background: "#293349", // Lacivert arka plan
        border: "15px solid #00C26D", // Yeşil çerçeve
        overflow: "hidden", // Taşan içerikleri gizle
        borderRadius: "10px", // Yuvarlatılmış köşeler
      }}
    >
      {/* Slider Bileşeni */}
      <Slider {...settings}>
        <div
          style={{
            height: "100%", // Kapsayıcıya uyum
            display: "flex", // Merkezleme için
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 1
        </div>
        <div
          style={{
            height: "100%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 2
        </div>
        <div
          style={{
            height: "100%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 3
        </div>
      </Slider>
    </div>
  );
};

export default EventsSlider;
